import itertools
import math

N = 2021

def check_condition(K, N):
    """
    Checks if for any p, q in K, there exists r in K such that p+q-2r is a multiple of N.
    """
    for p, q in itertools.product(K, repeat=2):
        target_2r = (p + q) % N

        found_r = False
        for r in K:
            # Check if p + q = 2r (mod N)
            two_r = (2 * r) % N
            if target_2r == two_r:
                found_r = True
                break

        if not found_r:
            return False
    return True

# Test small sizes m=3, 4, 5
print("Testing m=3:")
# Test APs: K = {a, a+d, a+2d}. Start with a=0.
# Iterate d from 1 up to N-1 (since d=0 means all elements are a, which implies |K|=1 unless N is small)
m = 3
successful_examples = []
for d in range(1, 2021):
    K = { (i * d) % N for i in range(m) }
    # Ensure K has exactly m distinct elements (which it usually will if d is not too small relative to N/m)
    if len(K) < m:
        # This happens if m*d is a multiple of N, i.e., d is a multiple of N/gcd(m, N).
        continue

    if check_condition(K, N):
        # Store the structure (a=0, d)
        successful_examples.append((m, 0, d))

print(f"Found {len(successful_examples)} successful examples for m=3.")
# Display the first few if found
for example in successful_examples[:5]:
    m_val, a_val, d_val = example
    K_example = {(i * d_val) % N for i in range(m_val)}
    print(f"m={m_val}, a={a_val}, d={d_val}. K = {list(K_example)}")

